// Replays the events up to `today` on top of a freshly built plan.
function stateOn(planStages, events, today) {
  const stages = planStages.map((s) => ({ ...s }));
  (events || []).filter((e) => e[0] <= today).forEach(([date, key, status, note]) => {
    const s = stages.find((x) => x.stage_key === key);
    s.status = status;
    s.status_since = date;
    s.done_on = status === 'done' ? date : '';
    if (note) s.note = note;
  });
  return stages;
}

