// Same history as the rules eval, frozen on one date. Both email types for every open project = 10 drafts.
const { EVENTS, CANARIES } = $('Test scenarios').first().json;
const TODAY = '2026-11-09';
const stateOn = (planStages, events) => {
  const stages = planStages.map((s) => ({ ...s }));
  (events || []).filter((e) => e[0] <= TODAY).forEach(([date, key, status, note]) => {
    const s = stages.find((x) => x.stage_key === key);
    s.status = status; s.status_since = date; s.done_on = status === 'done' ? date : '';
    if (note) s.note = note;
  });
  return stages;
};
const plans = $input.all().map((i) => i.json);
return [{ json: {
  eval_run: true, today: TODAY, draft_mode: 'both', eval_canaries: CANARIES,
  eval_projects: plans.map(({ stages, ...p }) => p),
  eval_stages: plans.flatMap((p) => stateOn(p.stages, EVENTS[p.project_id])),
} }];

const runAt = $now.setZone('Europe/Warsaw').toFormat('yyyy-MM-dd HH:mm');
const runId = 'drafts-' + $now.toFormat('yyyyMMddHHmmss');
const rows = $input.all().map((i, n) => {
  const d = i.json;
  if (d.is_canary) {
    const caught = String(d.check_notes).split(' | ').some((f) => f.startsWith(d.expect));
    return { run_id: runId, run_at: runAt, suite: 'drafts', checkpoint: d.canary_id, project: d.project_id, sim_date: '2026-11-09',
      what_it_tests: 'Canary: ' + d.what, expected: 'flag: ' + d.expect, actual: caught ? 'flag: ' + d.expect : 'not caught (' + d.check_notes + ')', passed: caught, detail: d.check_notes };
  }
  return { run_id: runId, run_at: runAt, suite: 'drafts', checkpoint: 'D' + String(n + 1).padStart(2, '0'), project: d.project_id, sim_date: '2026-11-09',
    what_it_tests: 'AI draft (' + d.kind + '): dates and stages match the table, nothing promised outside scope', expected: 'All checks passed',
    actual: d.check_notes, passed: d.check_passed === true, detail: d.subject + ' || ' + d.body };
});
const drafts = rows.filter((r) => r.checkpoint.startsWith('D'));
const canaries = rows.filter((r) => r.checkpoint.startsWith('C'));
const summary = { checkpoints: rows.length, passed: rows.filter((r) => r.passed).length, failed: rows.filter((r) => !r.passed).length,
  pass_pct: Math.round((rows.filter((r) => r.passed).length / rows.length) * 100), false_flags: 0,
  missed_flags: canaries.filter((r) => !r.passed).length,
  mistakes: 'AI drafts passed ' + drafts.filter((r) => r.passed).length + '/' + drafts.length + '; canaries caught ' + canaries.filter((r) => r.passed).length + '/' + canaries.length + '. ' +
    rows.filter((r) => !r.passed).map((r) => r.checkpoint + ': ' + r.actual).join(' || ') };
return rows.map((r) => ({ json: { ...r, summary } }));
